import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Recent developments","description":"Dated primary-source developments that affect the draft RAG architecture.","frontmatter":{"title":"Recent developments","description":"Dated primary-source developments that affect the draft RAG architecture."},"headers":[],"relativePath":"research/recent-developments.md","filePath":"research/recent-developments.md","lastUpdated":1794376220000}'),o={name:"research/recent-developments.md"};function i(s,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="recent-developments" tabindex="-1">Recent developments <a class="header-anchor" href="#recent-developments" aria-label="Permalink to &quot;Recent developments&quot;">​</a></h1><p><strong>Sources checked: November 5, 2026.</strong> This snapshot covers useful developments from November 5, 2025 through November 5, 2026. Dates below identify a release, announcement, merged change, paper revision, or documentation update; they are not search-engine crawl dates. Project claims are distinguished from implications for our design. Nothing here establishes a performance result for our corpus or application.</p><h2 id="october-28-2026-—-docling-improves-document-structure-and-ocr-recovery" tabindex="-1">October 28, 2026 — Docling improves document structure and OCR recovery <a class="header-anchor" href="#october-28-2026-—-docling-improves-document-structure-and-ocr-recovery" aria-label="Permalink to &quot;October 28, 2026 — Docling improves document structure and OCR recovery&quot;">​</a></h2><p><strong>Type: software release, v2.144.0.</strong> The release adds heading-hierarchy processing and an OCR path for replacing broken PDF text layers. It also includes reading-order and concurrent OCR fixes. These are relevant to the extraction stage before chunking, NER, and entity disambiguation. <a href="https://github.com/docling-project/docling/releases/tag/v2.144.0" target="_blank" rel="noreferrer">Release notes</a>, <a href="https://github.com/docling-project/docling" target="_blank" rel="noreferrer">Docling project</a></p><p>For our DAG, parser versions must be dependencies of chunks and extracted claims. A conversion change can alter section boundaries, text, and evidence anchors even when the source file is unchanged. Include malformed text layers, multi-column pages, and tables in parser regression fixtures. These fixes do not establish that every PDF is extracted correctly or that OCR confidence measures relationship accuracy.</p><h2 id="october-1-2026-—-sqlite-documents-its-own-ann-extension" tabindex="-1">October 1, 2026 — SQLite documents its own ANN extension <a class="header-anchor" href="#october-1-2026-—-sqlite-documents-its-own-ann-extension" aria-label="Permalink to &quot;October 1, 2026 — SQLite documents its own ANN extension&quot;">​</a></h2><p><strong>Type: documentation update, not a verified launch date.</strong> SQLite&#39;s Vec1 page is explicitly dated October 1 and identifies version 0.8. It documents approximate nearest-neighbor search using IVFADC/OPQ, cosine and L2 distance, and SIMD support. Vec1 is an extension, not a capability to assume in every installed SQLite build. <a href="https://sqlite.org/vec1.html" target="_blank" rel="noreferrer">Dated overview</a>, <a href="https://sqlite.org/vec1doc.html" target="_blank" rel="noreferrer">User manual</a></p><p>This broadens our unified SQLite retrieval evaluation beyond exact vector scans. Benchmark Vec1 against an exact baseline and a dedicated retrieval service using the same eligible documents. Filter behavior, recall, index training, updates, and deletion costs matter. The documentation date does not show when each feature first shipped; an ANN index also does not remove SQLite&#39;s write-concurrency or deployment constraints.</p><h2 id="september-4-2026-—-temporal-s-rust-sdk-reaches-general-availability" tabindex="-1">September 4, 2026 — Temporal&#39;s Rust SDK reaches general availability <a class="header-anchor" href="#september-4-2026-—-temporal-s-rust-sdk-reaches-general-availability" aria-label="Permalink to &quot;September 4, 2026 — Temporal&#39;s Rust SDK reaches general availability&quot;">​</a></h2><p><strong>Type: GA announcement in the product changelog.</strong> Temporal records Rust SDK general availability on September 4; a longer explanation was published September 23. The SDK supports Rust workflows, activities, and workers, with recorded execution history and recovery. <a href="https://temporal.io/changelog/rust-sdk-generally-available" target="_blank" rel="noreferrer">GA changelog</a>, <a href="https://temporal.io/blog/build-durable-applications-rust-temporal-rust-sdk-now-generally-available" target="_blank" rel="noreferrer">Detailed announcement</a>, <a href="https://docs.temporal.io/develop/rust" target="_blank" rel="noreferrer">Rust documentation</a></p><p>Rust-native orchestration is therefore a current candidate rather than a hypothetical custom scheduler. Compare it with Dagster against our dependency tracking, backfills, cancellation, and artifact-publication requirements. Whichever engine wins should own workflow progression. NATS can carry system events at its boundaries. GA status does not establish end-to-end exactly-once database/model effects or prove better throughput than the alternatives; our idempotent commits and revision guards remain necessary.</p><h2 id="august-14-2026-—-microsoft-graphrag-adds-a-maintenance-mode-notice" tabindex="-1">August 14, 2026 — Microsoft GraphRAG adds a maintenance-mode notice <a class="header-anchor" href="#august-14-2026-—-microsoft-graphrag-adds-a-maintenance-mode-notice" aria-label="Permalink to &quot;August 14, 2026 — Microsoft GraphRAG adds a maintenance-mode notice&quot;">​</a></h2><p><strong>Type: merged repository/documentation change.</strong> Pull request 2486 added a README notice stating that the project is largely in maintenance mode, with bug fixes and dependency updates continuing as appropriate, while new features and contributions are restricted. The merge date is August 14. <a href="https://github.com/microsoft/graphrag/pull/2486" target="_blank" rel="noreferrer">Dated change</a>, <a href="https://github.com/microsoft/graphrag" target="_blank" rel="noreferrer">Current project notice</a></p><p>GraphRAG remains useful as a reference pipeline and evaluation implementation for extraction, graph organization, and evidence retrieval. Its upstream roadmap should not be assumed to supply our entity-resolution corrections, streaming service, or incremental publication semantics. This maintenance decision concerns that implementation; it does not establish that graph-assisted retrieval as a technique is obsolete or ineffective.</p><h2 id="june-8-2026-—-unweaver-offers-an-entity-centric-retrieval-baseline" tabindex="-1">June 8, 2026 — UnWeaver offers an entity-centric retrieval baseline <a class="header-anchor" href="#june-8-2026-—-unweaver-offers-an-entity-centric-retrieval-baseline" aria-label="Permalink to &quot;June 8, 2026 — UnWeaver offers an entity-centric retrieval baseline&quot;">​</a></h2><p><strong>Type: arXiv paper revision, v3.</strong> UnWeaver extracts entity descriptions, aggregates them, searches their vector representations, and follows links back to original passages. It offers a lighter alternative to full relationship-graph construction. The source explicitly identifies June 8 as the v3 revision date. <a href="https://arxiv.org/abs/2603.29875" target="_blank" rel="noreferrer">Paper and history</a>, <a href="https://arxiv.org/html/2603.29875v3" target="_blank" rel="noreferrer">Method explanation</a>, <a href="https://github.com/SamsungLabs/UnWeaver" target="_blank" rel="noreferrer">Author-linked code</a></p><p>Our evaluation should include an entity-to-passage baseline alongside BM25/vector fusion and typed graph expansion. That isolates whether explicit edges improve our questions enough to justify their extraction and maintenance. The paper&#39;s name-based entity grouping does not satisfy our contextual disambiguation requirement by itself. Its reported results do not establish that graphs are unnecessary across domains, and we have not reproduced its experiments.</p><h2 id="march-31-2026-—-sqlite-vec-introduces-ann-indexes-in-an-alpha" tabindex="-1">March 31, 2026 — sqlite-vec introduces ANN indexes in an alpha <a class="header-anchor" href="#march-31-2026-—-sqlite-vec-introduces-ann-indexes-in-an-alpha" aria-label="Permalink to &quot;March 31, 2026 — sqlite-vec introduces ANN indexes in an alpha&quot;">​</a></h2><p><strong>Type: prerelease, v0.1.10-alpha.1.</strong> The release introduces rescore and DiskANN paths and describes IVF as experimental and disabled. This is a version-specific development: it makes a blanket claim that sqlite-vec cannot perform ANN inaccurate, while retaining an important prerelease qualification. <a href="https://github.com/asg017/sqlite-vec/releases/tag/v0.1.10-alpha.1" target="_blank" rel="noreferrer">Initial alpha release</a>, <a href="https://github.com/asg017/sqlite-vec/releases" target="_blank" rel="noreferrer">Project releases</a></p><p>For our candidate matrix, keep a stable exact-search baseline separate from experimental ANN builds. Pin versions and test filtered recall, deletion, replacement, portability, and ingestion contention before selecting one. The presence of an ANN implementation does not establish production suitability, sufficient metadata filtering, or a latency advantage for our data. It is also distinct from SQLite&#39;s Vec1 extension.</p><h2 id="march-12-2026-—-vite-8-adopts-rolldown" tabindex="-1">March 12, 2026 — Vite 8 adopts Rolldown <a class="header-anchor" href="#march-12-2026-—-vite-8-adopts-rolldown" aria-label="Permalink to &quot;March 12, 2026 — Vite 8 adopts Rolldown&quot;">​</a></h2><p><strong>Type: stable-release announcement.</strong> Vite 8 moves to the Rust-based Rolldown bundler and documents associated tooling and migration changes. The announcement concerns the build toolchain used by frontend frameworks. <a href="https://vite.dev/blog/announcing-vite8" target="_blank" rel="noreferrer">Vite announcement</a>, <a href="https://vite.dev/guide/migration" target="_blank" rel="noreferrer">Migration documentation</a></p><p>This is relevant when selecting compatible tooling for the proposed SvelteKit application. The VitePress documentation site has its own dependency constraints, so a major Vite upgrade should follow framework compatibility rather than be forced independently. Build-speed claims do not establish faster token delivery, lower input delay, or smoother Markdown rendering in the deployed browser. Those remain browser-benchmark questions.</p><h2 id="what-to-evaluate-next" tabindex="-1">What to evaluate next <a class="header-anchor" href="#what-to-evaluate-next" aria-label="Permalink to &quot;What to evaluate next&quot;">​</a></h2><p>Prioritize filtered SQLite retrieval comparisons, an entity-centric retrieval baseline, and a short durable-workflow recovery exercise. Use parser fixtures to verify evidence anchors across upgrades. Preserve the existing separation between ingestion, live answer serving, and frontend rendering: these developments expand our options without proving that additional stages or services improve the experience.</p>',25)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
